const raw = $input.first().json.output;
let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
text = text.replace(/```json|```/g, '').trim();
try {
  return [{ json: JSON.parse(text) }];
} catch (e) {
  return [{ json: { error: 'invalid_json', raw: text } }];
}

const rec = $input.first().json;
const intake = $('Combine').first().json;
const src = $('Code in JavaScript3').first().json;

const issues = [];
const norm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const idOf = u => (String(u ?? '').match(/\/(\d{4,})-/) || [])[1] || null;

// 0. The agent output was not valid JSON
if (rec.error) {
  issues.push({ product: null, rule: 'invalid_json', detail: 'Recommendation output was not valid JSON' });
  return [{ json: { rules_verdict: 'fail', issues, recommendation: rec } }];
}

const recs = Array.isArray(rec.recommendations) ? rec.recommendations : [];
const min = intake.budget_tnd?.min ?? null;
const max = intake.budget_tnd?.max ?? null;
const excluded = (intake.brand_excluded || []).map(norm);

const pool = {
  knowledge_base: src.knowledge_base?.products || [],
  live_search: src.live_search?.products || []
};

// Empty result must be explained
if (recs.length === 0 && !rec.note) {
  issues.push({ product: null, rule: 'empty_without_note', detail: 'No recommendations and no explanation in note' });
}

// Max 3
if (recs.length > 3) {
  issues.push({ product: null, rule: 'too_many', detail: `${recs.length} recommendations, maximum is 3` });
}

for (const r of recs) {
  // 1. Groundedness (KB: source_id, live: URL matched by numeric product ID, fallback: name)
  const list = pool[r.source] || [];
  const match =
    list.find(p => p.source_id && p.source_id === r.source_ref) ||
    list.find(p => p.url && idOf(p.url) && idOf(p.url) === idOf(r.source_ref)) ||
    list.find(p => norm(p.name) === norm(r.name));

  if (!match) {
    issues.push({ product: r.name, rule: 'ungrounded', detail: `No ${r.source} entry matches source_ref "${r.source_ref}"` });
  } else {
    if ((match.price_tnd ?? null) !== (r.price_tnd ?? null)) {
      issues.push({ product: r.name, rule: 'price_mismatch', detail: `Source says ${match.price_tnd ?? 'null'}, recommendation says ${r.price_tnd ?? 'null'}` });
    }
    // URL must be copied exactly, not "corrected" by the model
    if (r.source === 'live_search' && match.url && r.source_ref !== match.url) {
      issues.push({ product: r.name, rule: 'url_altered', detail: `source_ref differs from the real URL: ${match.url}` });
    }
  }

  // 2. Budget
  if (r.price_tnd != null) {
    if (max != null && r.price_tnd > max) issues.push({ product: r.name, rule: 'over_budget', detail: `${r.price_tnd} > max ${max}` });
    if (min != null && r.price_tnd < min) issues.push({ product: r.name, rule: 'under_budget', detail: `${r.price_tnd} < min ${min}` });
  }

  // 3. Excluded brands (name match only; the LLM layer will catch e.g. "iPhone" vs "Apple")
  if (excluded.some(b => b && norm(r.name).includes(b))) {
    issues.push({ product: r.name, rule: 'excluded_brand', detail: 'Product belongs to an excluded brand' });
  }

  // 4. Null price must not claim budget compliance
  if (r.price_tnd == null && /(within|fits?|respects?|under|meets?)\s+(the\s+|your\s+)?budget|dans\s+(le\s+|votre\s+)?budget/i.test(r.why || '')) {
    issues.push({ product: r.name, rule: 'null_price_claim', detail: 'Claims budget fit while price is unknown' });
  }
}

return [{ json: { rules_verdict: issues.length ? 'fail' : 'pass', issues, recommendation: rec } }];

const items = $input.all().map(i => i.json);
const data = items.find(d => Array.isArray(d.products) && d.products.some(p => p.url)) || items[0];
if (data.error || !Array.isArray(data.products)) return [{ json: data }];

const intake = $('Combine').first().json;
const max = intake.budget_tnd?.max ?? null;
const min = intake.budget_tnd?.min ?? null;

const toNumber = s => {
  let t = String(s).replace(/[\s\u00a0]/g, '');
  if (t.includes('.') && t.includes(',')) t = t.replace(/\./g, '').replace(',', '.');
  else if (t.includes(',')) t = t.replace(',', '.');
  const n = parseFloat(t);
  return Number.isFinite(n) ? Math.round(n) : null;
};

const patterns = [
  /property=["']product:price:amount["'][^>]*content=["']([^"']+)["']/i,
  /content=["']([^"']+)["'][^>]*property=["']product:price:amount["']/i,
  /itemprop=["']price["'][^>]*content=["']([^"']+)["']/i,
  /content=["']([^"']+)["'][^>]*itemprop=["']price["']/i,
  /"price"\s*:\s*"?([\d.,\s]+)"?/i,
  /class=["'][^"']*(?:current-price|product-price)[^"']*["'][^>]*>[\s\S]{0,300}?(\d[\d\s\u00a0.,]*)\s*(?:DT|TND)/i
];

const extractPrice = html => {
  for (let i = 0; i < patterns.length; i++) {
    const m = html.match(patterns[i]);
    if (m) {
      const n = toNumber(m[1]);
      if (n && n > 0) return { price: n, pattern: i };
    }
  }
  return null;
};

for (const p of data.products) {
  if (p.url) p.url = p.url.split('?')[0];
  if (p.price_tnd != null || !p.url) continue;
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: p.url,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml',
        'Accept-Language': 'fr-FR,fr;q=0.9'
      },
      returnFullResponse: true,
      encoding: 'text',
      json: false,
      timeout: 15000
    });
    const html = typeof res.body === 'string' ? res.body : String(res.body ?? '');
    const found = extractPrice(html);
    if (found) {
      p.price_tnd = found.price;
      p.currency_note = 'Price extracted from the product page';
      p.price_debug = `ok (pattern ${found.pattern})`;
    } else {
      const i = html.search(/\d[\d\s\u00a0]*[.,]\d{3}\s*(?:DT|TND)/i);
      p.price_debug = `page fetched (${html.length} chars), no pattern matched`;
      p.price_context = i >= 0 ? html.slice(Math.max(0, i - 250), i + 60) : 'no "xxx,000 DT" text found in page';
    }
  } catch (e) {
    p.price_debug = `fetch failed: ${e.message}`;
  }
}

const inputCount = data.products.length;
const kept = [];
const removed = [];
for (const p of data.products) {
  const ok = p.price_tnd == null ||
    ((max == null || p.price_tnd <= max) && (min == null || p.price_tnd >= min));
  (ok ? kept : removed).push(p);
}

data.products = kept;
data.removed_by_budget = removed.map(p => ({ name: p.name, price_tnd: p.price_tnd, debug: p.price_debug }));

const withPrice = kept.filter(p => p.price_tnd != null).length;
if (inputCount === 0) {
  data.note = 'The search agent returned no product pages.';
} else if (kept.length === 0) {
  data.note = `All ${inputCount} product(s) were above the budget after price extraction.`;
} else {
  data.note = `${kept.length} product page(s) found; ${withPrice} price(s) confirmed from the product pages, ${kept.length - withPrice} unconfirmed.`;
}

return [{ json: data }];

const raw = $input.first().json.output;
let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
text = text.replace(/```json|```/g, '').trim();

// Keep only the part between the first { and the last }
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start !== -1 && end > start) text = text.slice(start, end + 1);

let verdict;
try {
  verdict = JSON.parse(text);
} catch (e) {
  return [{ json: {
    verdict: 'error',
    issues: [{ product: null, rule: 'invalid_json', detail: 'Verifier output was not valid JSON' }],
    raw: text
  } }];
}

// Normalize: make sure verdict and issues are always present and consistent
const issues = Array.isArray(verdict.issues) ? verdict.issues : [];
const normalized = issues.length > 0 ? 'fail' : (verdict.verdict === 'fail' ? 'fail' : 'pass');

// Carry the rules result and the recommendation forward for the next steps
const rules = $('Verify (rules)').first().json;

return [{ json: {
  verdict: normalized,
  issues,
  rules_verdict: rules.rules_verdict,
  rules_issues: rules.issues,
  recommendation: rules.recommendation
} }];

const v = $input.first().json;
const rules = $('Verify (rules)').first().json;

// Attempt number of the run being verified
let attempt = 0;
try {
  attempt = $('Prepare retry').isExecuted
    ? $('Prepare retry').last().json.attempt
    : $('Init attempt').first().json.attempt;
} catch (e) {}

const issues = [...(rules.issues || []), ...(v.issues || [])];
const failed = rules.rules_verdict === 'fail' || v.verdict !== 'pass';

return [{ json: { failed, attempt, issues, recommendation: rules.recommendation } }];

const g = $input.first().json;
const init = $('Init Attempt').first().json;
return [{ json: {
  ...init,
  attempt: g.attempt + 1,
  verifier_feedback: g.issues
} }];

const g = $input.first().json;
const rec = g.recommendation || {};
const flagged = new Set(
  (g.issues || []).map(i => i.product).filter(Boolean)
);
const kept = (rec.recommendations || []).filter(r => !flagged.has(r.name));

return [{ json: {
  recommendations: kept,
  comparison: kept.length === (rec.recommendations || []).length ? (rec.comparison ?? null) : null,
  note: kept.length === 0
    ? 'No reliable recommendation could be verified for this request. Please refine your criteria (budget, brand, use case) and try again.'
    : 'Some options were removed because they failed verification. ' + (rec.note || '')
} }];

const r = $input.first().json;
const lang = r.language || 'fr';

const T = {
  fr: {
    error: "Je n'ai pas bien compris votre demande. Pouvez-vous la reformuler (type de produit, budget, usage) ?",
    out_of_scope: "Je suis ShopMind, un assistant pour l'achat de produits électroniques (laptops, smartphones, tablettes, accessoires). Je ne peux pas répondre à cette question."
  },
  en: {
    error: "I couldn't understand your request. Could you rephrase it (product type, budget, usage)?",
    out_of_scope: "I'm ShopMind, an assistant for buying electronics (laptops, smartphones, tablets, accessories). I can't answer that question."
  },
  ar: {
    error: "لم أفهم طلبك. هل يمكنك إعادة صياغته (نوع المنتج، الميزانية، الاستخدام)؟",
    out_of_scope: "أنا ShopMind، مساعد لشراء المنتجات الإلكترونية (حواسيب، هواتف، ألواح، ملحقات). لا يمكنني الإجابة عن هذا السؤال."
  }
};

const t = T[lang] || T.fr;

const cats = Array.isArray(r.categories) ? r.categories : [];
const multi = !r.router_error && cats.length > 1 && ['recommend', 'compare'].includes(r.intent);

const multiMsg = {
  fr: `Votre demande concerne plusieurs produits (${cats.join(', ')}). Pour de meilleurs résultats, demandez-les un par un avec un budget pour chacun.`,
  en: `Your request covers several products (${cats.join(', ')}). For better results, ask for them one at a time with a budget for each.`,
  ar: `طلبك يشمل عدة منتجات (${cats.join(', ')}). للحصول على أفضل النتائج، اطلبها واحداً تلو الآخر مع ميزانية لكل منتج.`
};

const reply_type = r.router_error ? 'router_error' : (multi ? 'multi_product' : 'out_of_scope');
const note = r.router_error ? t.error : (multi ? (multiMsg[lang] || multiMsg.fr) : t.out_of_scope);

return [{ json: {
  failed: false,
  attempt: 0,
  issues: [],
  reply_type,
  recommendation: { recommendations: [], note }
} }];

const raw = $input.first().json.output;
let text = (typeof raw === 'string' ? raw : (raw == null ? '' : JSON.stringify(raw)))
  .replace(/```json|```/g, '').trim();
const s = text.indexOf('{'), e = text.lastIndexOf('}');
if (s !== -1 && e > s) text = text.slice(s, e + 1);

const lang = $('Code in JavaScript').first().json.language || 'fr';
const sorry = {
  fr: "Je n'ai pas pu répondre de façon fiable à cette question. Pouvez-vous la reformuler ?",
  en: "I couldn't answer this question reliably. Could you rephrase it?",
  ar: "لم أتمكن من الإجابة عن هذا السؤال بشكل موثوق. هل يمكنك إعادة صياغته؟"
}[lang] || "I couldn't answer this question reliably.";

let answer = '', confidence = 'low';
try {
  const j = JSON.parse(text);
  answer = String(j.answer || '').trim();
  confidence = j.confidence || 'low';
} catch (err) {}

return [{ json: {
  failed: false,
  attempt: 0,
  issues: [],
  reply_type: 'direct_answer',
  confidence,
  recommendation: { recommendations: [], note: answer || sorry }
} }];

let s = String(query).toLowerCase()
  .replace(/(\d)[\s.](\d{3})\b/g, '$1$2')   // 2 500 / 2.500 -> 2500
  .replace(/,/g, '.');
const rate = /(€|eur)/.test(s) ? 3.35 : /(\$|usd|dollar)/.test(s) ? 3.10 : 1;
const num = (v, k) => Math.round(parseFloat(v) * (k ? 1000 : 1) * rate);
let min = null, max = null, m;
if ((m = s.match(/entre\s*([\d.]+)\s*(k?)\s*(?:et|à|-)\s*([\d.]+)\s*(k?)/))) {
  min = num(m[1], m[2]); max = num(m[3], m[4]);
} else if ((m = s.match(/(?:moins de|max(?:imum)?|jusqu'?à|under|below|<)\s*([\d.]+)\s*(k?)/))
  || (m = s.match(/([\d.]+)\s*(k?)\s*(?:dt|tnd|dinars?|€|eur|\$|usd)?\s*max/))
  || (m = s.match(/(?:environ|autour de|about|around|~)\s*([\d.]+)\s*(k?)/))) {
  max = num(m[1], m[2]);
} else if ((m = s.match(/(?:plus de|min(?:imum)?|à partir de|over|above)\s*([\d.]+)\s*(k?)/))) {
  min = num(m[1], m[2]);
}
return JSON.stringify({ min, max, converted_from_foreign_currency: rate !== 1 });

const k = String(query).toLowerCase().replace(/[^a-z0-9]/g, '');
const db = {
  usbc: 'USB-C: reversible connector; can carry data, charging (USB Power Delivery) and sometimes video. Capabilities depend on the device.',
  hdmi: 'HDMI: carries digital video and audio to a screen or TV.',
  magsafe: 'MagSafe: magnetic charging connector found on some MacBook models.',
  lightning: 'Lightning: Apple proprietary connector used on older iPhones and accessories.',
  usba: 'USB-A: rectangular legacy USB port, not reversible.',
  microusb: 'Micro-USB: older small connector, not reversible, common on older phones and accessories.'
};
return db[k] || 'Unknown connector: no information available.';
